"""Pending pointer and object-output mechanisms read in vsprintf.c 741–1147."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'관찰·디버깅','lib/vsprintf.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('Pointer Hash 초기화·Publish와 Memory Barrier','fill_ptr_key',
      '주소를 로그에 그대로 노출하지 않기 위한 key 준비 과정에서 초기화와 공개 순서를 배웁니다.',
      'fill_ptr_key는 get_random_bytes로 ptr_key를 채운 뒤 smp_wmb를 실행하고 WRITE_ONCE로 filled_random_ptr_key를 true로 바꿉니다. __ptr_to_hashval은 READ_ONCE로 준비 flag를 보고 smp_rmb 뒤 key를 사용합니다. vsprintf_init_hashval은 초기화된 RNG에서 callback이 실행되도록 notifier를 execute_with_initialized_rng에 전달합니다.',
      'Key byte 초기화, barrier, 준비 flag 공개를 한 프로토콜로 읽습니다. READ_ONCE만으로 모든 자료의 동기화가 끝났다고 설명하지 않습니다. 단일 thread 모의 시험은 이 순서를 관찰할 뿐 실제 여러 CPU memory ordering의 증명이 아닙니다.',
      'key 쓰기→wmb→flag 공개와 flag 읽기→rmb→key 사용을 연결하세요.',
      [('Key를 채우기 전에 준비 flag를 공개하면 가능한 문제는?', '다른 CPU가 아직 준비되지 않은 key를 사용할 수 있다','flag 이름만 달라져 결과는 언제나 같다','준비 flag는 key를 읽어도 된다는 신호입니다. 원본은 자료 쓰기와 공개 사이, 읽기와 자료 접근 사이에 대응 barrier를 둡니다.'),
       ('RNG callback을 등록하는 초기화 함수는?', 'vsprintf_init_hashval','skip_atoi','vsprintf_init_hashval은 notifier의 callback을 fill_ptr_key로 정하고 RNG 초기화 실행 경로에 넘깁니다.')],
      [('자료 위치 표식','ptr_key와 flag의 __read_mostly는 자주 읽는 자료의 배치 표식입니다. 읽기 전용 보장이나 lock 자체라고 해석하지 않습니다.'),
       ('초기 Boot 옵션','debug_boot_weak_hash_enable은 early_param으로 선택할 수 있는 약한 hash 설정입니다. 원본이 비암호학적 조기 debug 용도라고 명시하므로 기본 SipHash 정책과 구분합니다.')])
    lesson('Pointer Hash 값·준비 실패와 32bit 식별자','__ptr_to_hashval',
      '로그용 주소 식별자가 실제 주소 및 충돌 없는 객체 ID와 어떻게 다른지 이해합니다.',
      'Key 준비 flag가 false이면 -EBUSY를 반환하며 출력 매개변수에 값을 대입하지 않습니다. 준비되면 64bit CONFIG에서는 siphash_1u64 결과를 0xffffffff와 AND하여 32bit만 남깁니다. 다른 분기는 siphash_1u32를 사용합니다. 계산 결과를 hashval_out에 저장하고 0을 반환하며 ptr_to_hashval은 이 helper를 감쌉니다.',
      '반환 코드를 먼저 확인한 뒤 출력값을 사용합니다. 출력된 32bit hash를 실제 주소로 역참조하거나 충돌 없는 전역 ID로 사용하지 않습니다. 같은 pointer의 표시에 쓰이는 정책이며 hash 충돌 가능성은 존재합니다.',
      'EBUSY 이전 출력 대입 여부, CONFIG 분기, mask, 결과 반환을 읽으세요.',
      [('Key가 준비되지 않았으면 hashval_out은?', '이 함수가 갱신하지 않는다','언제나 0을 써서 성공을 반환한다','조기 -EBUSY 반환이 출력 대입보다 앞에 있습니다. 기존 출력값을 성공 결과로 사용하지 않습니다.'),
       ('64bit 분기의 표시 값으로 서로 다른 주소의 충돌이 불가능한가?', '32bit 값이므로 충돌할 수 있다','모든 64bit 주소가 유일하게 보존된다','64bit 주소 공간보다 결과 공간이 작습니다. 로그용 hash를 유일성을 보장하는 주소 대체값으로 사용할 수 없습니다.')],
      [('원본 주석 해석','주석의 unique identifier 표현만으로 수학적 무충돌 계약을 만들지 않습니다. 실제 mask와 결과 공간을 보고 가능한 충돌을 이해합니다.'),
       ('출력과 객체 수명','Hash 계산은 pointer 값을 처리합니다. 객체를 참조로 고정하거나 유효 mapping을 확인하는 함수가 아닙니다. 표시 값과 객체 lifetime은 별도입니다.')])
    lesson('기본 Pointer 출력·Hash와 준비 전 Placeholder','ptr_to_id',
      '부팅 초기부터 로그가 나오는 상황에서 주소 노출 정책과 key 미준비 처리를 연결합니다.',
      'ptr_to_id는 NULL과 error pointer에는 실제 값 표시 보조를 사용합니다. Debug weak 설정이면 hash_long을 사용하고, 일반 경로에서 key가 아직 없으면 주소 크기에 맞는 ptrval placeholder를 error_string으로 출력합니다. 준비된 값은 pointer_string으로 표시합니다. default_pointer는 no_hash_pointers 설정이면 실제 주소를 출력하고 그렇지 않으면 ptr_to_id를 호출합니다.',
      '기본 출력, 명시적 no_hash_pointers 설정, 조기 weak debug 경로를 구분합니다. Key가 없을 때 placeholder를 실제 값 0이나 객체 부재로 해석하지 않습니다. NULL·error 표현은 실제 객체 주소가 아니라 특별 값이라는 원본 설명과 연결합니다.',
      'IS_ERR_OR_NULL→weak→정상 hash→placeholder와 default_pointer의 옵션을 읽으세요.',
      [('정상 pointer지만 key가 아직 준비되지 않으면?', 'ptrval placeholder를 출력한다','주소가 무조건 그대로 공개된다','__ptr_to_hashval의 실패에 해당하는 placeholder branch가 있습니다. 기본 미준비 처리는 실제 주소 표시가 아닙니다.'),
       ('no_hash_pointers를 켜면 기본 표시 정책은?', 'pointer_string으로 실제 값을 표시한다','더 강한 hash를 자동 선택한다','default_pointer의 해당 조건은 hash 함수를 건너뛰고 주소 숫자 표시 helper를 호출합니다.')],
      [('서로 다른 크기','sizeof(ptr)==8이면 (____ptrval____), 아니면 (ptrval)을 선택합니다. 기본 폭 2*sizeof(ptr)에 맞추는 표시이며 실제 하드웨어 pointer 검증을 수행하지 않습니다.'),
       ('로그 해석','같은 boot key에서 hash가 같다는 사실만으로 객체가 계속 살아 있거나 두 로그의 객체가 반드시 같다고 결론 내리지 않습니다. 재사용된 주소와 충돌도 고려합니다.')])
    lesson('Restricted Pointer·권한과 Read 시점 검사','restricted_pointer',
      '파일을 연 시점과 내용을 읽는 시점의 권한이 달라질 수 있어 로그 주소 표시를 추가 제한하는 원리를 배웁니다.',
      'kptr_restrict 0은 default_pointer입니다. 1은 hardirq·softirq·NMI에서 pK-error를 출력합니다. 일반 context에서는 CAP_SYSLOG와 euid==uid 및 egid==gid를 확인하고 실패하면 ptr를 NULL로 바꿉니다. 2와 그 외 값도 NULL로 바꿉니다. 마지막 pointer_string이 선택된 값을 숫자로 출력합니다.',
      '제한 설정 값과 호출 context, 현재 credentials를 함께 확인합니다. 파일 open 때 검사했다고 read 때 주소 공개가 자동 허용된다고 생각하지 않습니다. NULL로 바꾼 출력은 대상 객체 자체를 변경하거나 해제하는 동작이 아닙니다.',
      'switch의 0·1·2/default, interrupt 검사, 두 ID 비교를 읽으세요.',
      [('kptr_restrict=1이며 euid와 uid가 다르면?', '표시할 pointer를 NULL로 바꾼다','CAP_SYSLOG와 관계없이 실제 주소를 항상 출력한다','원본 조건은 capability와 두 credentials 동일성 모두를 요구합니다. 어느 하나가 실패해도 실제 값을 숨깁니다.'),
       ('kptr_restrict=1의 NMI 호출은?', 'pK-error를 출력한다','일반 task의 권한을 그대로 믿고 주소를 출력한다','IRQ context의 capability 판정이 의미 없다는 원본 이유로 해당 context를 별도 오류 표시합니다.')],
      [('권한 변경 시나리오','파일을 연 뒤 privilege를 높인 process가 read 시점에 주소를 얻는 문제를 막으려는 검사입니다. 파일 descriptor의 접근 허용과 주소 공개 정책의 시점을 구분합니다.'),
       ('Zero 출력의 의미','정책에 따른 NULL 표시와 실제 pointer가 NULL인 경우가 출력상 같을 수 있습니다. 이 값만 보고 원래 객체의 존재 여부를 확정하지 않습니다.')])
    lesson('Dentry 이름 출력·부모 경로와 RCU 구간','dentry_name',
      '파일 이름을 출력하는 코드도 부모 연결과 문자열 수명 보호가 필요하며 전체 경로 생성과 계약이 다를 수 있습니다.',
      'fmt[1]이 2·3·4이면 그 깊이만큼, 그 외에는 한 단계까지 d_parent와 d_name.name을 READ_ONCE로 모읍니다. RCU read 구간에서 pointer를 확인하고 parent==self인 root에서 멈춥니다. 가장 위에서부터 이름을 읽고 사이에 slash를 넣으며 precision과 출력 buffer를 적용한 뒤 unlock하고 widen_string을 호출합니다. file_dentry_name은 file의 f_path.dentry를 전달합니다.',
      '선택 깊이의 이름 표시로 사용하고 mount 전체를 반영한 절대 pathname API라고 해석하지 않습니다. RCU 보호와 rename에 대한 일관된 snapshot 보장을 구분합니다. 연결을 따라가는 동안 read 구간을 유지합니다.',
      '최대 4개의 array, self-parent root, 역순 이름 출력, 모든 unlock 경로를 읽으세요.',
      [('fmt 깊이가 3이면 언제나 전체 절대 경로를 만드는가?', '최대 세 단계의 dentry 이름만 표시한다','mount 연결까지 무제한 탐색한다','고정 array[4]와 정해진 depth로 부모를 읽습니다. Mount traversal이나 전체 pathname 구축은 없습니다.'),
       ('중간 pointer 검사 실패 경로에서 RCU lock은?', 'unlock한 뒤 반환한다','다음 호출까지 계속 유지한다','오류 branch가 rcu_read_unlock을 수행합니다. 정상 끝에서도 unlock한 뒤 폭 padding을 적용합니다.')],
      [('Root 처리','부모가 자기 자신이면 더 올라갈 수 없습니다. 이미 아래 이름을 모았다면 root 이름은 빈 문자열로 바꿔 separator 표현을 맞춥니다.'),
       ('모의 시험 범위','단일 thread의 dentry tree로 depth와 separator를 검증할 수 있습니다. 그것만으로 동시 rename·삭제의 실제 RCU 수명 관리를 검증했다고 보고하지 않습니다.')])
    lesson('Block Device 이름·숫자 끝 이름의 Partition 구분','bdev_name',
      '장치 이름에 partition 번호를 붙일 때 이름 자체가 숫자로 끝나는 경우를 어떻게 구분하는지 배웁니다.',
      'CONFIG_BLOCK의 bdev_name은 bdev pointer를 확인하고 bd_disk의 disk_name을 문자열로 출력합니다. Partition이면 이름의 마지막 글자가 숫자인지 보고 숫자이면 p를 추가한 뒤 bdev_partno를 number로 출력합니다. Partition이 아니면 disk_name만 반환합니다.',
      '유효 block_device와 gendisk의 수명을 보장하고 선택 CONFIG를 확인합니다. 이름이 숫자로 끝나는 nvme 계열과 sd 계열의 구분 규칙을 관찰합니다. 이 helper는 device 생성이나 partition 탐색을 수행하지 않습니다.',
      'bdev_is_partition 조건, 마지막 문자 isdigit, p 추가, partno 출력을 읽으세요.',
      [('nvme0n1 이름에 partition 2를 붙이는 표시는?', 'nvme0n1p2이다','nvme0n12이다','기본 이름이 숫자로 끝나므로 p를 넣어 이름의 마지막 숫자와 partition 번호를 구분합니다.'),
       ('sda 이름의 partition 2는?', 'sda2이다','sdap2를 항상 만든다','마지막 글자가 숫자가 아니므로 p를 추가하지 않고 번호를 붙입니다.')],
      [('설정과 계약','CONFIG_BLOCK이 아닌 빌드에는 이 body가 포함되지 않습니다. 이름 문자열과 disk 참조는 호출자가 유효하게 유지해야 합니다.'),
       ('Spec 전달','번호 출력에도 전달된 spec을 사용합니다. 상위 formatter가 어떤 width·base·precision을 제공하는지 연결해야 실제 전체 표시를 판단할 수 있습니다.')])
    lesson('Symbol 출력·Kallsyms와 Build ID 분기','symbol_string',
      '로그에 주소 대신 함수 이름과 offset을 표시할 때 symbol 정보 설정과 format suffix가 선택하는 경로를 배웁니다.',
      'fmt[1]==R이면 __builtin_extract_return_addr로 return address 표현을 조정합니다. CONFIG_KALLSYMS에서는 B·Bb에 backtrace 또는 build ID backtrace, S의 b·Rb suffix에 build ID symbol, s에 offset 없는 symbol, 나머지에 일반 symbol을 사용합니다. KALLSYMS가 없으면 pointer 크기 폭의 special_hex_number를 출력합니다.',
      '사용한 suffix와 커널 symbol 정보 설정을 확인합니다. Symbol이 없는 numeric fallback을 formatter 실패로 단정하지 않습니다. Build ID 표시와 실제 실행 파일 식별의 관계를 읽고 주소가 유효 코드 위치인지 caller의 계약을 확인합니다.',
      'R 추출, B·S·s 분기, CONFIG 없는 hex fallback을 읽으세요.',
      [('CONFIG_KALLSYMS가 없으면 이 helper는?', '주소를 special hex 형태로 표시한다','항상 빈 문자열을 반환한다','조건부 대체 경로는 special_hex_number입니다. Symbol 자료가 없는 상태에서도 숫자 표현을 제공합니다.'),
       ('소문자 s 분기는 어떤 symbol helper를 쓰는가?', 'sprint_symbol_no_offset','sprint_backtrace_build_id','대소문자 format은 서로 다른 의미입니다. s는 offset 없는 symbol 이름 경로입니다.')],
      [('Return Address','__builtin_extract_return_addr는 architecture의 return address 표현을 조정하는 compiler 기능입니다. 모든 pointer에 필요한 일반 hash 함수가 아닙니다.'),
       ('표시 모드의 범위','이 함수는 symbol 조회 보조의 결과를 문자열로 출력합니다. Unwinding 전체 과정이나 symbol table 생성 알고리즘은 해당 구현을 별도 읽어야 합니다.')])
    lesson('Resource 출력·종류별 진법과 Flag 해독','resource_string',
      '장치 resource 범위의 start·end와 flags를 사람이 읽을 수 있는 진단 표현으로 조합하는 원리를 배웁니다.',
      'IO·MEM·IRQ·DMA·BUS flag 순서로 종류와 출력 spec을 고릅니다. R format의 decode이고 UNSET이면 주소 대신 resource_size를 표시하며 그렇지 않으면 start와 다른 end를 hyphen으로 연결합니다. Decode이면 64bit·pref·window·disabled flag를 이름으로 붙이고 raw mode이면 flags를 hex로 표시합니다. 내부 sym을 NUL 종료한 뒤 외부 string_nocheck로 복사합니다.',
      'Resource 종류와 format의 R/raw 선택을 같이 확인합니다. UNSET의 size 표시를 실제 배정된 주소로 해석하지 않습니다. 출력은 진단용이며 resource reservation이나 IO mapping을 수행하지 않습니다.',
      '종류 선택, decode와 UNSET, start==end, named flags와 raw flags를 읽으세요.',
      [('Decode mode에서 UNSET resource는?', 'size를 표시한다','반드시 배정된 start 주소만 표시한다','이 branch는 size 문자열과 resource_size(res)를 사용합니다. 아직 주소 배정으로 해석하지 않습니다.'),
       ('알 수 없는 resource 종류에서는 named decode가 유지되는가?', 'decode를 0으로 바꾸고 raw flags를 표시한다','모든 flag 이름을 자동으로 추론한다','마지막 종류 branch는 ???를 출력하고 decode=0입니다. 뒤쪽에서 flags numeric 경로를 선택합니다.')],
      [('범위의 끝','원본에서 resource_size는 end-start+1인 inclusive resource 계약과 연결됩니다. 가상 주소 VMA의 일반 end-exclusive 길이 공식과 혼동하지 않습니다.'),
       ('내부와 외부 Buffer','내부 sym은 예상 최대 종류·범위·flag 표현을 담도록 크기를 계산합니다. 내부 종료를 붙여도 외부 출력 helper의 NUL 종료 계약이 자동 생기는 것은 아닙니다.')])
